import argparse
import csv
import importlib
import json
import os
import random

import numpy as np
import pandas as pd
import torch
from tqdm import tqdm
from transformers import AutoModelForCausalLM, AutoTokenizer

JUDGE_PAIRWISE_SYSTEM_PROMPT = (
    "You are an expert medical evaluator. Your task is to act as an impartial judge and evaluate the quality of "
    "responses generated by two AI models. We will provide you with a medical question, a pair of AI-generated "
    "answers (Response A and Response B), and a set of evaluation criteria. You should first read the medical "
    "question carefully, then evaluate the quality of the responses with regard to each criterion by comparing "
    "the two responses. Answer the question asked in each criterion and provide a brief explanation for your "
    "verdict. Avoid positional biases and ensure that the order in which the responses are presented does not "
    "influence your decision. Do not allow the length of the responses to influence your evaluation. Be as "
    "objective as possible. Output your final verdict for each criterion by strictly following this format: "
    '"response_a" if Response A is your choice, "response_b" if Response B is your choice, '
    'or "tie" in case of a draw.'
)

def set_seed(seed=42):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


def build_user_prompt(question: str, response_a: str, response_b: str, criteria_pairwise: list, base_model_prompt: bool = False) -> str:
    criteria_block = "\n".join(
        f"[The Start of {label} Criterion]\n{criterion_question}\n[The End of {label} Criterion]\n"
        for _, label, criterion_question in criteria_pairwise
    )
    json_schema = "{\n" + ",\n".join(
        f'  "{label}": {{"verdict": "[verdict]", "reason": "[explanation]"}}' for _, label, _ in criteria_pairwise
    ) + "\n}"

    header = f"""## Medical Question: {question}
[The Start of Response A]
{response_a}
[The End of Response A]
[The Start of Response B]
{response_b}
[The End of Response B]
[The Start of Evaluation Criteria]

{criteria_block}
[The End of Evaluation Criteria]

[Output Format]
Please provide your evaluation results in the following JSON format by filling in the placeholders in []:
{json_schema}
"""
    if base_model_prompt:
        return header + "\nAnswer:\n"
    return header


def load_jsonl(path: str) -> list:
    data = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            data.append(json.loads(line))
    return data


def load_csv(path: str) -> list:
    with open(path, "r", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))


def infer_names(rows_a: list, rows_b: list, dataset_name_override: str, model_a_fallback: str, model_b_fallback: str):
    first_a = rows_a[0] if rows_a else {}
    first_b = rows_b[0] if rows_b else {}
    model_a_name = first_a.get("model_name") or model_a_fallback #model name
    model_b_name = first_b.get("model_name") or model_b_fallback  #model name
    dataset_name = dataset_name_override or first_a.get("dataset") or first_b.get("dataset") #dataset name
    return model_a_name, model_b_name, dataset_name


def main():
    set_seed(42)

    parser = argparse.ArgumentParser(description="Step 1: generate raw pairwise llm-as-a-judge responses")
    parser.add_argument("--csv_path_a", type=str, required=True,
                         help="CSV with Response A's generations")
    parser.add_argument("--csv_path_b", type=str, required=True,
                         help="CSV with Response B's generations")
    parser.add_argument("--jsonl_path", type=str, required=True,
                         help="Question/reference jsonl matching the dataset used to generate the model's responses")
    parser.add_argument("--dataset_name", type=str, default=None,
                         help="Override the dataset name inferred from the csvs")
    parser.add_argument("--model_a_name", type=str, default=None,
                         help="Fallback name for Response A if $CSV_PATH_A has no 'model_name' column") #This occurs in the generations of the base model
    parser.add_argument("--model_b_name", type=str, default=None,
                         help="Fallback name for Response B if $CSV_PATH_B has no 'model_name' column") #This occurs in the generations of the base model
    parser.add_argument("--run_type", type=str, required=True,
                         help="Differentiates where results are stored")
    parser.add_argument("--judge_model_name", type=str, required=True)
    parser.add_argument("--judge_model_path", type=str, required=True)
    parser.add_argument("--is_instruct", action=argparse.BooleanOptionalAction, default=True)
    parser.add_argument("--prefix_force_json", action="store_true",
                         help="To base models that produced an empty output (append a literal '{' to the end of the prompt)")
    parser.add_argument("--alternate_order", action="store_true",
                         help="Alternate the order of the evaluated models responses")
    parser.add_argument("--criteria_module", type=str,
                         help="Evaluation criteria")
    parser.add_argument("--output_dir", type=str, required=True)
    parser.add_argument("--max_length", type=int, default=8000)
    parser.add_argument("--max_new_tokens", type=int, default=1500)
    args = parser.parse_args()

    criteria_pairwise = importlib.import_module(args.criteria_module).CRITERIA_PAIRWISE

    print(f"Loading judge model {args.judge_model_name}...")
    tokenizer = AutoTokenizer.from_pretrained(args.judge_model_path)
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token

    model = AutoModelForCausalLM.from_pretrained(
        args.judge_model_path,
        device_map="auto",
        torch_dtype=torch.bfloat16,
        attn_implementation="eager",
    )
    model.eval()

    reference_data = load_jsonl(args.jsonl_path) #evaluation dataset
    rows_a = load_csv(args.csv_path_a) #dataset with the responses to evaluate
    rows_b = load_csv(args.csv_path_b) #dataset with the responses to evaluate

    model_a_name, model_b_name, dataset_name = infer_names(
        rows_a, rows_b, args.dataset_name, args.model_a_name, args.model_b_name
    )
    order_note = " - alternating A/B position per question" if args.alternate_order else ""
    print(f"\nJudging '{model_a_name}' (Response A) vs '{model_b_name}' (Response B) on '{dataset_name}'{order_note}")

    if not (len(rows_a) == len(rows_b) == len(reference_data)): #confirms if the number of the responses generated are the same as the questions in the evaluation dataset
        raise ValueError(
            f"Row count mismatch: csv_path_a has {len(rows_a)} rows, csv_path_b has {len(rows_b)} rows, "
            f"jsonl has {len(reference_data)} rows. Refusing to match positionally."
        )

    results = []
    for i, (row_a, row_b, ref_item) in enumerate(tqdm(list(zip(rows_a, rows_b, reference_data)))):
        instruction = ref_item.get("instruction", "").strip()
        user_input = ref_item.get("input", "").strip()
        question = f"{instruction}\n\n{user_input}".strip()
        reference_answer = ref_item.get("output", "").strip()

        position_swapped = args.alternate_order and (i % 2 == 1) 
        if position_swapped:
            response_a = row_b["model_generation"].strip()
            response_b = row_a["model_generation"].strip()
        else:
            response_a = row_a["model_generation"].strip()
            response_b = row_b["model_generation"].strip()

        for label, row in (("A", row_a), ("B", row_b)):
            if reference_answer != row["expected_reference"].strip():
                print(f"[WARNING] Row {i}: csv_path_{label.lower()} expected_reference does not match jsonl output.")

        if args.is_instruct:
            user_prompt = build_user_prompt(question, response_a, response_b, criteria_pairwise)
            try:
                messages = [
                    {"role": "system", "content": JUDGE_PAIRWISE_SYSTEM_PROMPT},
                    {"role": "user", "content": user_prompt},
                ]
                prompt = tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
                if i == 0:
                    print(f"\n[TEMPLATE INFO] Judge model {args.judge_model_name} accepted 'system role'.\n")
            except Exception:
                messages = [{"role": "user", "content": f"{JUDGE_PAIRWISE_SYSTEM_PROMPT}\n\n{user_prompt}"}]
                prompt = tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
                if i == 0:
                    print(f"\n[TEMPLATE INFO] Judge model {args.judge_model_name} rejected 'system role'. Falling back to 'user role'.\n")
        else:
            user_prompt = build_user_prompt(question, response_a, response_b, criteria_pairwise, base_model_prompt=True)
            prompt = f"{JUDGE_PAIRWISE_SYSTEM_PROMPT}\n\n{user_prompt}"
            if args.prefix_force_json:
                prompt += "{"

        inputs = tokenizer(
            prompt,
            return_tensors="pt",
            truncation=True,
            max_length=args.max_length,
            add_special_tokens=True,
        ).to(model.device)

        input_length = inputs["input_ids"].shape[1]
        if input_length >= args.max_length:
            print(f"[WARNING] Judge prompt for question {i + 1} was TRUNCATED! (Length: {input_length} / Max: {args.max_length})")

        with torch.no_grad():
            outputs = model.generate(
                **inputs,
                max_new_tokens=args.max_new_tokens,
                do_sample=False,
                temperature=None,
                top_p=None,
                pad_token_id=tokenizer.pad_token_id,
            )

        generated_tokens = outputs[0][input_length:]
        raw_output = tokenizer.decode(generated_tokens, skip_special_tokens=True).strip()
        if args.prefix_force_json:
            raw_output = "{" + raw_output 

        results.append({
            "question_id": i,
            "dataset": dataset_name,
            "run_type": args.run_type,
            "model_a": model_a_name,
            "model_b": model_b_name,
            "position_swapped": position_swapped,
            "judge_model": args.judge_model_name,
            "question": question,
            "response_a": response_a,
            "response_b": response_b,
            "prompt_used": prompt,
            "judge_raw_output": raw_output,
        })

    out_dir = os.path.join(args.output_dir, args.judge_model_name, args.run_type, f"{model_a_name}_vs_{model_b_name}")
    os.makedirs(out_dir, exist_ok=True)
    out_stem = os.path.join(out_dir, f"{dataset_name}_judge_pairwise_raw")

    df = pd.DataFrame(results)
    df.to_json(f"{out_stem}.json", orient="records", indent=2, force_ascii=False)

    print(f"Saved raw judge responses to {out_stem}.json")


if __name__ == "__main__":
    main()
